const shiftInUse = `-- name: ShiftInUse :one
SELECT (EXISTS (SELECT 1 FROM hr.employee_shifts es WHERE es.shift_id = $1::text)
    OR EXISTS (SELECT 1 FROM hr.attendance a WHERE a.shift_id = $1::text))::boolean AS used
`

func (q *Queries) ShiftInUse(ctx context.Context, id string) (bool, error) {
	row := q.db.QueryRow(ctx, shiftInUse, id)
	var used bool
	err := row.Scan(&used)
	return used, err
}

